      for (const w of game.walls) for (let k = 0; k < w.tiles.length; k += 3) { const t = w.tiles[k], d = tileDist(t, r.lx, r.ly); if (owner[t] && d < 12 && d + 2 < sd) { sd = d + 2; sp = t; } }
