      const rate = k === 'wheat' ? n * WH.perTile * farm * C.staff * worldFarm() * (1 + ((C.fx && C.fx.wheat) || 0)) : n * CFG.prodPerTile[k] * hard * (rig ? CFG.power.rigMult * (C.sat ?? 1) : b.type === 'refinery' ? C.staff * (C.sat ?? 1) : C.staff);
