    useWorld(0);
    const data = worldSave();
    data.worlds = WORLDS.map(P => P.id && worldData[P.id] ? onWorld(P.id, worldSave) : null);
    if (was !== 0 && camOf[0]) data.cam = camOf[0];   // the view saved is home's
    useWorld(was);
