  ctx.setLineDash([5, 4]); ctx.lineWidth = 2; ctx.strokeStyle = '#f2c14e';
  ctx.beginPath(); ctx.arc(sx, sy, r, 0, Math.PI * 2); ctx.stroke(); ctx.setLineDash([]);
  pill(sx, sy - r - 16, 'Click to lock on', { fg: '#f2c14e', border: '#f2c14e', size: 12 });
