    if (bx < -50 || by < -50 || bx > cw + 50 || by > ch + 50) continue;
    const top = Math.max(-40, by - ch), gr = ctx.createLinearGradient(bx, top, bx, by);
    gr.addColorStop(0, 'rgba(255,220,140,0)'); gr.addColorStop(1, `rgba(255,250,210,${0.85 * p})`);
