  game.bombers.push({ x0, y0, x1: tx + 0.5, y1: ty + 0.5, d: 0, len: Math.hypot(tx + 0.5 - x0, ty + 0.5 - y0), back: false, hit: 0, w: WORLD, home: A.i });
