  btns.push({ label: 'Counter…', act: counter || (() => { dipMsg = `<span class="d">↔ Countering ${n.short}'s offer (${title.replace(/<[^>]+>/g, '')}): set your terms and send them.</span>`; openDiplomacy(n); }) });
