    if (goldOf(C) < g) return toast(`${C.short} needs ${g} gold for ${MARKET.lot} ${r}`);
    if (C.store && C.res[r] + MARKET.lot > C.store[r] + 0.5) return toast(`${C.short} has no room for ${MARKET.lot} more ${r}`);
