  if (goldOf(C) < g) return toast(`${C.short} needs ${g} gold to hire ${MERC.n} troops`);
  C.res.gold -= g; b.units = (b.units || 0) + Math.min(MERC.n, room);
  floatText(b.i % W + 0.5, ((b.i / W) | 0) - 1, `+${Math.min(MERC.n, Math.floor(room))} hired`, '#f2c14e');
