    if (!underway(b) && !b.site && from.includes(b.type) && isUnlocked(t)) btns.push({ label: `Upgrade: ${d.name}`, act: () => { showBuildingCard(null); setTool(t); if (game.ghost) { game.ghost.i = b.i; game.ghost.set = true; updateConfirm(); } } });
