  const x = i % W, y = (i / W) | 0;
  aiOf[i] = 0;
  if (!WORLD) { n.tiles = Math.max(0, n.tiles - 1); n.sx -= x; n.sy -= y; if (n.tiles) { n.lx = n.sx / n.tiles + 0.5; n.ly = n.sy / n.tiles + 0.5; } }   // a nation's numbers count its home land only
