  const out = { t: 'world', worlds, nations, lost: RIV.lost, won: RIV.won, hostDmg: Math.round(RIV.hostDmg), destroyed: RIV.destroyed };
  RIV.lost = []; RIV.won = []; RIV.hostDmg = 0; RIV.destroyed = [];
